package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="categories") public class Category{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String name;private String description;private String imageUrl;private boolean active=true;private Integer sortOrder=0;private Instant createdAt=Instant.now();private Instant updatedAt=Instant.now();public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public Integer getSortOrder(){return sortOrder;}public void setSortOrder(Integer v){sortOrder=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void touch(){updatedAt=Instant.now();}}
